"""File storage backends: local disk (`data/media`) or S3-compatible object storage.

Both implement the same interface: `save(key, data, content_type)`,
`delete(key)`, `url(key)`, `exists(key)`. The backend is chosen by
`STORAGE_BACKEND`. Keys look like `vehicles/12/<uuid>_1000.webp`.
"""

from __future__ import annotations

import logging
import re
from functools import lru_cache
from pathlib import Path

from app.config import get_settings

log = logging.getLogger(__name__)

# Keys are generated by the app; this pattern is a defence-in-depth check.
_KEY_RE = re.compile(r"^[A-Za-z0-9][A-Za-z0-9_\-/]*\.[a-z0-9]{2,5}$")


def is_safe_key(key: str) -> bool:
    return bool(_KEY_RE.match(key)) and ".." not in key and "//" not in key


class LocalStorage:
    """Stores files under `data/media` (outside the webroot); served by the `/media` route."""

    def __init__(self, root: Path, media_url: str = "") -> None:
        self.root = root
        self.media_url = media_url.rstrip("/")
        self.root.mkdir(parents=True, exist_ok=True)

    def _path(self, key: str) -> Path:
        if not is_safe_key(key):
            raise ValueError(f"Invalid storage key: {key!r}")
        path = (self.root / key).resolve()
        if not path.is_relative_to(self.root.resolve()):
            raise ValueError("Path traversal attempt")
        return path

    def save(self, key: str, data: bytes, content_type: str = "image/webp") -> None:
        path = self._path(key)
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_bytes(data)

    def delete(self, key: str) -> None:
        try:
            self._path(key).unlink(missing_ok=True)
        except ValueError:
            log.warning("Refusing to delete invalid key %r", key)

    def exists(self, key: str) -> bool:
        try:
            return self._path(key).exists()
        except ValueError:
            return False

    def read(self, key: str) -> bytes:
        return self._path(key).read_bytes()

    def url(self, key: str) -> str:
        base = self.media_url or "/media"
        return f"{base}/{key}"


class S3Storage:
    """S3-compatible object storage (Cloudflare R2, Hetzner Object Storage, AWS S3)."""

    def __init__(
        self,
        endpoint: str,
        bucket: str,
        access_key: str,
        secret_key: str,
        region: str = "auto",
        media_url: str = "",
    ) -> None:
        import boto3  # imported lazily; only needed for this backend

        self.bucket = bucket
        self.endpoint = endpoint.rstrip("/")
        self.media_url = media_url.rstrip("/")
        self.client = boto3.client(
            "s3",
            endpoint_url=endpoint or None,
            aws_access_key_id=access_key,
            aws_secret_access_key=secret_key,
            region_name=region or "auto",
        )

    def save(self, key: str, data: bytes, content_type: str = "image/webp") -> None:
        if not is_safe_key(key):
            raise ValueError(f"Invalid storage key: {key!r}")
        self.client.put_object(
            Bucket=self.bucket,
            Key=key,
            Body=data,
            ContentType=content_type,
            CacheControl="public, max-age=31536000, immutable",
        )

    def delete(self, key: str) -> None:
        self.client.delete_object(Bucket=self.bucket, Key=key)

    def exists(self, key: str) -> bool:
        try:
            self.client.head_object(Bucket=self.bucket, Key=key)
            return True
        except Exception:  # noqa: BLE001 - botocore raises ClientError for 404
            return False

    def read(self, key: str) -> bytes:
        return self.client.get_object(Bucket=self.bucket, Key=key)["Body"].read()

    def url(self, key: str) -> str:
        if self.media_url:
            return f"{self.media_url}/{key}"
        return f"{self.endpoint}/{self.bucket}/{key}"


@lru_cache
def get_storage() -> LocalStorage | S3Storage:
    settings = get_settings()
    if settings.STORAGE_BACKEND == "s3":
        return S3Storage(
            endpoint=settings.S3_ENDPOINT,
            bucket=settings.S3_BUCKET,
            access_key=settings.S3_ACCESS_KEY,
            secret_key=settings.S3_SECRET_KEY,
            region=settings.S3_REGION,
            media_url=settings.MEDIA_URL,
        )
    return LocalStorage(settings.media_dir, settings.MEDIA_URL)
